package com.crh.logon.webservices.clients.beans.deliverydocument;

import java.io.Serializable;

/**
 * @author AdNovum Informatik AG
 * 
 * Data Transfer Object from business tier to the webservice client 
 * tier. This object will be created and filled in the business tier, and 
 * converted/read in the webservices-client tier into the data model for SAP
 * as generated by AXIS.
 * 
 * Please use business terms for the fields in this object, usually the wsdl's
 * documentation for a field is OK. Just don't use the SAP names like VKORG, 
 * VTWEG etc.
 */
public class QualifierExtraDataDTO implements Serializable {

	/**
	 * WS field to SAP: SalesDocumentCreation / sales_document_notification / document_header_general_data (E1EDK01) / document_header_qualifier_extra_data (ZE1EDK3) / ZQUALZ
	 */
	private String qualifierType;
	public static final String QUALIFIER_TYPE_TRAILER_INFORMATION = "001";
	
	/**
	 * WS field to SAP: SalesDocumentCreation / sales_document_notification / document_header_general_data (E1EDK01) / document_header_qualifier_extra_data (ZE1EDK3) / ZCUSADD
	 */
	private String dataValue1;
	
	/**
	 * WS field to SAP: SalesDocumentCreation / sales_document_notification / document_header_general_data (E1EDK01) / document_header_qualifier_extra_data (ZE1EDK3) / ZCUSADD_BEZ
	 */
	private String dataValue2;

	public String getQualifierType() {
		return qualifierType;
	}

	public void setQualifierType(String qualifierType) {
		this.qualifierType = qualifierType;
	}

	public String getDataValue1() {
		return dataValue1;
	}

	public void setDataValue1(String dataValue1) {
		this.dataValue1 = dataValue1;
	}

	public String getDataValue2() {
		return dataValue2;
	}

	public void setDataValue2(String dataValue2) {
		this.dataValue2 = dataValue2;
	}
}
